"""Original bounded checks for public technical and professional instruction.

Publisher material reviewed on 2026-11-10 and 2026-11-11. Course indexes and
occupation summaries are ungraded. These are short knowledge checks, with the
instructional scope recorded for each lesson.
"""
import hashlib

REVIEWED_AT = "2026-11-10"
BANKS, NEW_RESOURCES, ORIENTATIONS = [], [], []
SOURCE_FINDINGS = []
LEGACY_QUESTION_FINDINGS = []  # No legacy answer correction asserted without evidence.
TOPICS = set("api testing linux networking cloud security architecture containers data-engineering cad manufacturing quality visual-design content seo research product customer-research ux mobile ml-operations automation electronics technical-writing brand".split())


def _new(url, topic, title, provider, description):
    rid = "lesson-resource-" + hashlib.sha256((url + "|" + topic).encode()).hexdigest()[:20]
    NEW_RESOURCES.append({"id": rid, "title": title, "url": url, "provider": provider,
                          "description": description, "text": description, "topics": [topic],
                          "type": "tutorial", "difficulty": "beginner", "estimated_hours": None,
                          "source": "VoidFill public instructional source review 2026-11-10",
                          "license": "Original metadata; linked material retains publisher license"})
    return rid


def _b(ids, url, topics, scope, sections, rows, evidence=()):
    BANKS.append({"resource_ids": ids, "url": url, "topics": [topics] if isinstance(topics, str) else topics,
                  "scope": scope, "reviewed_at": REVIEWED_AT, "source_sections": sections,
                  "source_evidence_urls": list(evidence),
                  "source_anchor_note": "Named instructional sections reviewed; no unverified heading fragments invented.",
                  "questions": [(code, code, level, prompt, answer, wrong, explanation, "")
                                for code, level, prompt, answer, wrong, explanation in rows]})


def _g(ids, url, topic, reason, children, kind="reference-directory"):
    ORIENTATIONS.append({"resource_ids": ids, "url": url, "topics": [topic], "reason": reason,
                         "child_resource_ids": list(children), "kind": kind, "reviewed_at": REVIEWED_AT})


def _finding(resource_id, section, detail, warning, references):
    bank = next(record for record in BANKS if resource_id in record["resource_ids"])
    SOURCE_FINDINGS.append({
        "resource_id": resource_id,
        "url": bank["url"],
        "section": section,
        "severity": "error",
        "detail": detail,
        "warning": warning,
        "correct_primary_urls": references,
        "reviewed_at": "2026-11-11",
    })


